import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import yaml

app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = '/tmp/conversions'
app.config['MAX_CONTENT_LENGTH'] = 10 * 1024 * 1024

ALLOWED_EXTENSIONS = {'yaml', 'yml', 'json'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def load_config(config_path):
    """Load conversion configuration from YAML file."""
    with open(config_path, 'r') as f:
        config = yaml.safe_load(f)
    return config

def validate_template(template_data):
    """Validate template structure has required fields."""
    required = ['version', 'output_format', 'transformations']
    for field in required:
        if field not in template_data:
            raise ValueError(f"Missing required field: {field}")
    if template_data['version'] not in ['1.0', '1.1', '2.0']:
        raise ValueError("Unsupported template version")
    return True

def apply_transformations(input_path, template_data, output_dir):
    """Apply document transformations using system tools."""
    output_format = template_data['output_format']
    output_file = os.path.join(output_dir, f"output.{output_format}")

    for transform in template_data.get('transformations', []):
        tool = transform.get('tool', 'cat')
        args = transform.get('args', [])

        # Build command - tool must be in allowed list
        allowed_tools = ['pandoc', 'wkhtmltopdf', 'libreoffice', 'convert', 'gs']
        if tool not in allowed_tools:
            raise ValueError(f"Tool '{tool}' not in allowed list")

        cmd = [tool] + args + [input_path, output_file]

        # Execute transformation
        result = subprocess.run(
            cmd,
            capture_output=True,
            timeout=30,
            cwd=output_dir
        )

        if result.returncode != 0:
            raise RuntimeError(f"Transform failed: {result.stderr.decode()[:200]}")

        input_path = output_file

    return output_file

@app.route('/api/v1/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document using specified template."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if not file or not allowed_file(file.filename):
        return jsonify({'error': 'Invalid file type'}), 400

    template_name = request.form.get('template', 'default')

    # Load template configuration
    template_path = f"/etc/converter/templates/{template_name}.yaml"
    if not os.path.exists(template_path):
        return jsonify({'error': 'Template not found'}), 404

    try:
        template_data = load_config(template_path)
        validate_template(template_data)
    except (ValueError, yaml.YAMLError) as e:
        return jsonify({'error': f'Invalid template: {str(e)}'}), 400

    # Save uploaded file
    work_dir = tempfile.mkdtemp(dir=app.config['UPLOAD_FOLDER'])
    filename = secure_filename(file.filename)
    input_path = os.path.join(work_dir, filename)
    file.save(input_path)

    try:
        output_path = apply_transformations(input_path, template_data, work_dir)
        return send_file(output_path, as_attachment=True)
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/v1/templates', methods=['GET'])
def list_templates():
    """List available conversion templates."""
    template_dir = '/etc/converter/templates'
    templates = []
    for f in os.listdir(template_dir):
        if f.endswith('.yaml'):
            templates.append(f.replace('.yaml', ''))
    return jsonify({'templates': templates})

@app.route('/api/v1/templates/<name>', methods=['PUT'])
def update_template(name):
    """Update or create a conversion template (admin only)."""
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'Unauthorized'}), 401

    # Token validation delegated to upstream auth service
    template_content = request.get_json()
    if not template_content:
        return jsonify({'error': 'Invalid JSON body'}), 400

    try:
        validate_template(template_content)
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

    safe_name = secure_filename(name)
    template_path = f"/etc/converter/templates/{safe_name}.yaml"

    with open(template_path, 'w') as f:
        yaml.dump(template_content, f)

    return jsonify({'status': 'updated', 'template': safe_name}), 200

if __name__ == '__main__':
    os.makedirs(app.config['UPLOAD_FOLDER'], exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
